// Half Adder Module
module half_adder (
  input  a,
  input  b,
  output sum,
  output carry
);
  assign sum   = a ^ b;   // XOR gate for sum calculation
  assign carry = a & b;   // AND gate for carry calculation
endmodule

// Full Adder Module using Two Half Adders and OR Gate
module full_adder (
  input  a,
  input  b,
  input  carry_in,
  output sum,
  output carry_out
);
  // Internal wires to connect components
  wire half1_sum, half1_carry, half2_carry;

  // First half adder: adds inputs a and b
  half_adder ha1 (
    .a    (a),
    .b    (b),
    .sum  (half1_sum),
    .carry(half1_carry)
  );

  // Second half adder: adds intermediate sum and carry_in
  half_adder ha2 (
    .a    (half1_sum),
    .b    (carry_in),
    .sum  (sum),        // Final sum output
    .carry(half2_carry)
  );

  // OR gate to combine carry signals
  assign carry_out = half1_carry | half2_carry;
endmodule

